from scipy.optimize import least_squares
def run(name,f,p0s):
    best=None
    for p0 in p0s:
        try:
            r=least_squares(lambda p: f(p)-dA_dt, p0, max_nfev=3000)
            e=np.mean(r.fun**2)/np.var(dA_dt)
            if best is None or e<best[0]: best=(e,r.x)
        except Exception as ex: pass
    print(name,best[0],np.round(best[1],4))
